const f = reformer.form();
f.field("login").required().minLength(3).maxLength(20).pattern(/^[A-Za-z0-9_]+$/, "Только латиница, цифры и _");
f.field("email").required().email();
f.field("password").required().minLength(8);
f.field("confirmPassword").required().sameAs("password", "Пароли не совпадают");
f.field("captcha").required().minLength(6).maxLength(6).asyncCheck(v => String(v).toUpperCase() === "ABC123", { delay: 300, message: "Символы не совпадают" });
